def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    # Count defections
    opp_def = sum(1 for _, b in history if b == 'D')
    my_def = sum(1 for a, _ in history if a == 'D')

    # Detect non-responsive opponent: if we defected and they cooperated multiple times recently
    if n >= 6:
        recent = history[-6:]
        dc_pairs = sum(1 for a, b in recent if a == 'D' and b == 'C')
        if dc_pairs >= 2:
            return 'D'

    # Exploit unconditional cooperator
    if opp_def == 0 and my_def >= 2:
        return 'D'

    # Very hostile opponent
    if n >= 10 and opp_def > 0.8 * n:
        return 'D'

    # Compute opponent defection streak
    opp_streak = 0
    for _, b in reversed(history):
        if b == 'D':
            opp_streak += 1
        else:
            break

    if opp_streak == 0:
        return 'C'
    elif opp_streak == 1:
        return 'C'  # forgive single defection
    else:
        # opp_streak >= 2
        if opp_streak >= 4 and opp_def < 0.3 * n:
            if history[-1][0] == 'C':
                return 'D'
            else:
                return 'C'
        else:
            return 'D'
